INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9801, '1 Chronicles 3:24', '1 Chronicles', 3, 24, '&nbsp;د اليوعينى اووۀ زامن وُو: هُوداوياه، اِلياسب، فلاياه، عقوب، يوحانان، دلاياه او عنانى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9802, '1 Chronicles 4:1', '1 Chronicles', 4, 1, '&nbsp;دا د يهوداه څۀ اولاد دے: فارص، حصرون، کرمى، حُور او سوبل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9803, '1 Chronicles 4:2', '1 Chronicles', 4, 2, '&nbsp;سوبل د رياياه پلار وو، چې دا د يحت پلار وو، چې هغه د اخومى او د لاهد پلار وو، کوم چې د هغه خلقو پلار نيکۀ وو چې په صُرعه کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9804, '1 Chronicles 4:5', '1 Chronicles', 4, 5, '&nbsp;اشور چا چې د تقوع ښار جوړ کړے وو د هغۀ دوه ښځې حيلاه او نعراه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9805, '1 Chronicles 4:6', '1 Chronicles', 4, 6, '&nbsp;د هغۀ د خپلې ښځې نعراه څلور زامن وُو: اخوسام، حِفر، تمنى او هخسترى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9806, '1 Chronicles 4:7', '1 Chronicles', 4, 7, '&nbsp;د اشور د خپلې ښځې حيلاه نه درې زامن وُو: ضرت، اِضهار او اِتنان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9807, '1 Chronicles 4:8', '1 Chronicles', 4, 8, '&nbsp;قوض د عنوب، ضوبيبه او د حروم د زوئ اخرخېل د قبيلو پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9808, '1 Chronicles 4:9', '1 Chronicles', 4, 9, '&nbsp;يو سړے وو چې نوم يې يعبيض وو، هغه په خپلو وروڼو کښې ډېر عزتمند سړے وو. په هغۀ باندې خپلې مور يعبيض نوم اېښے وو، ځکه چې د هغۀ د پېدا کېدو درد ډېر سخت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9809, '1 Chronicles 4:10', '1 Chronicles', 4, 10, '&nbsp;خو يعبيض د بنى اِسرائيلو خُدائ پاک ته سوال وکړو، ”خُدايه پاکه، تۀ به ما له برکت راکوې او زما مُلک به لويَوې. زما مل شه او د هر هغه خراب عمل نه مې وساته چې ما له تکليف راکوى.“ او چې هغۀ د څۀ سوال کړے وو نو خُدائ پاک هغه هر څۀ ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9810, '1 Chronicles 4:11', '1 Chronicles', 4, 11, '&nbsp;د سوخه د ورور کالب يو زوئ محير وو. محير د استون پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9811, '1 Chronicles 4:12', '1 Chronicles', 4, 12, '&nbsp;چې د هغۀ درې زامن وُو: بيت‌رفا، فاسح او تخِنه. تخِنه د ناحس ښار جوړ کړے وو. د دې سړو اولاد په ريکه کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9812, '1 Chronicles 4:13', '1 Chronicles', 4, 13, '&nbsp;د قنز دوه زامن عتنى‌اېل او شراياه وُو. د عتنى‌اېل هم دوه زامن حتت او معوناتى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9813, '1 Chronicles 4:14', '1 Chronicles', 4, 14, '&nbsp;معوناتى د عفره پلار وو. شراياه د يوآب پلار وو. او يوآب هغه وړومبے کس وو چې د ماهِرو خلقو وادى يې آباده کړه، ځکه چې هلته ټول خلق ماهِر کاريګران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9814, '1 Chronicles 4:15', '1 Chronicles', 4, 15, '&nbsp;د يفُنه زوئ کالب درې زامن وُو: عيرو، ايله او نعم. او ايله د قنز پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9815, '1 Chronicles 4:16', '1 Chronicles', 4, 16, '&nbsp;د يهلل‌ايل څلور زامن وُو: زيف، زيفه، تيرياه او اسرى‌اېل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9816, '1 Chronicles 4:19', '1 Chronicles', 4, 19, '&nbsp;هودياه د نحم خور وادۀ کړه. د هغوئ اولاد د جرمى ډله وه، چې هغه د قعيله په ښار کښې اوسېده او د معکې ډله چې د استموع په ښار کښې اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9817, '1 Chronicles 4:20', '1 Chronicles', 4, 20, '&nbsp;د سيمون څلور زامن وُو: امنون، رِنه، بِن‌حنان او تيلون. د يسعى دوه زامن وُو: زوحت او بِن‌زوحت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9818, '1 Chronicles 4:21', '1 Chronicles', 4, 21, '&nbsp;سيله د يهوداه د زامنو نه يو زوئ وو. د هغۀ په اولاد کښې عير شامل وو، چا چې د لکه ښار جوړ کړے وو، لعده چا چې د مريسه ښار جوړ کړے وو، د لټې کپړې جوړونکى قبيله چې د بيت‌اشبيع په ښار کښې اوسېده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9819, '1 Chronicles 4:22', '1 Chronicles', 4, 22, '&nbsp;يوقيم او هغه خلق چې د کوزيبا په ښار کښې اوسېدل، او يوآس او شراف، چا چې موآبيانې ښځې وادۀ کړې او په بيت‌لحم کښې اوسېدل. دا د ډېر پخوانى وخت حِساب کِتاب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9820, '1 Chronicles 4:23', '1 Chronicles', 4, 23, '&nbsp;هغوئ د بادشاه د خِدمت کُلالان وُو او د نتائيم او د جديره په ښارونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9821, '1 Chronicles 4:24', '1 Chronicles', 4, 24, '&nbsp;د شمعون پينځۀ زامن وُو: نمواېل، يمين، يريب، زارح او ساؤل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9822, '1 Chronicles 4:25', '1 Chronicles', 4, 25, '&nbsp;د ساؤل زوئ سلوم وو، د سلوم زوئ مِبسام وو او د مِبسام زوئ مِشماع وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9823, '1 Chronicles 4:26', '1 Chronicles', 4, 26, '&nbsp;د مِشماع د اولاد نسب‌نامه داسې ده: حمواېل، زکور او سِمعى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9824, '1 Chronicles 4:27', '1 Chronicles', 4, 27, '&nbsp;د سِمعى شپاړس زامن او شپږ لوڼه وې، خو د هغۀ د خپلوانو اولاد کم وو او د شمعون قبيله د يهوداه د قبيلې په شان لويه نۀ شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9825, '1 Chronicles 4:28', '1 Chronicles', 4, 28, '&nbsp;د داؤد بادشاه تر وخته پورې د شمعون اولاد په بيرسبع، مولاده، حصارسعول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9826, '1 Chronicles 4:29', '1 Chronicles', 4, 29, '&nbsp;بِلهاه، عضم، تولاد،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9827, '1 Chronicles 4:30', '1 Chronicles', 4, 30, '&nbsp;بتو‌اېل، حُرمه، صِقلاج،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9828, '1 Chronicles 4:31', '1 Chronicles', 4, 31, '&nbsp;بيت‌مرکبوت، حصار‌سوسم، بيت‌برائى او شعريم کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9829, '1 Chronicles 4:32', '1 Chronicles', 4, 32, '&nbsp;هغوئ په پينځو نورو ځايونو کښې هم اوسېدل: ايتام، عين، رِمون، توکن، عسن،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9830, '1 Chronicles 4:33', '1 Chronicles', 4, 33, '&nbsp;او په ګېرچاپېره کلو کښې، د بعلات ښار پورې. دا هغه حِساب کِتاب دے چې هغوئ د خپلو کورَنو او د هغه ځايونو په حقله ساتلو چې چرته هغوئ اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9831, '1 Chronicles 4:39', '1 Chronicles', 4, 39, '&nbsp;هغوئ تقريباً تر جدور پورې نمرپرېواتۀ طرف ته خوارۀ شول او د هغه مېدان نمرخاتۀ طرف ته يې خپلې ګډې څرولې چرته چې هغه ښار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9832, '1 Chronicles 4:40', '1 Chronicles', 4, 40, '&nbsp;هغوئ د څرن ښۀ آباد مُلکونه وموندل چې په کولاو مُلک کښې خوارۀ وارۀ وُو چې خاموش او د امن نه ډک وو. د هغوئ نه مخکښې چې کوم خلق هلته اوسېدل هغوئ حاميان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9833, '1 Chronicles 4:41', '1 Chronicles', 4, 41, '&nbsp;د يهوداه بادشاه حزقياه په وخت کښې د هغه ډلو مشران جرار ته لاړل او هلته يې حاميان او معونيان او د هغوئ خېمې تباه کړې او د هغوئ ټول خلق يې ووژل او تر نن ورځې پورې يې د نوم او نشان پته نۀ لګى. د هغوئ په ځايونو کښې په خپله آباد شول، ځکه چې هغوئ ته د رَمو دپاره د څرن د زمکې ضرورت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9834, '1 Chronicles 4:42', '1 Chronicles', 4, 42, '&nbsp;د شمعون قبيلې نور پينځۀ سوه کسان نمرخاتۀ طرف ادوم ته لاړل. د هغوئ مشرى د يسعى زامنو کوله: فلطياه، نعرياه، رفاياه او عُزى‌اېل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9835, '1 Chronicles 4:43', '1 Chronicles', 4, 43, '&nbsp;هلته هغوئ هغه پاتې شوى عماليقيان ووژل کوم چې تښتېدلى وُو او هغوئ تر ننه پورې هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9836, '1 Chronicles 5:1', '1 Chronicles', 5, 1, '&nbsp;دا د روبين اولاد دے چې هغه د يعقوب مشر زوئ وو. هغۀ د خپل پلار د بلې ښځې سره د زنا کولو په وجه د خپل پلار بې‌عزتى وکړه نو چې د مشرى زوئ کوم حقُونه هغۀ لرل، هغه ختم شول او هغه حقُونه يوسف ته مِلاو شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9837, '1 Chronicles 5:2', '1 Chronicles', 5, 2, '&nbsp;خو د يهوداه قبيله تکړه شوه او ټولو قبيلو له يې يو بادشاه ورکړو، خو پېدائشى حق د يوسف سره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9838, '1 Chronicles 5:3', '1 Chronicles', 5, 3, '&nbsp;د يعقوب د مشر زوئ روبين څلور زامن وُو: حنوک، فلو، حصرون او کرمى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9839, '1 Chronicles 5:7', '1 Chronicles', 5, 7, '&nbsp;د روبين په قبيله کښې د دې د قبيلو د مشرانو نسب‌نامه: يعى‌ايل، زکرياه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9840, '1 Chronicles 5:8', '1 Chronicles', 5, 8, '&nbsp;او بالع، د عزز زوئ او د سمع نمسے، چې د يوايل د قبيلې وو. دا قبيله په عروعير کښې او د هغه ځائ نه د نبو پورې او د بعل معون په علاقه کښې اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9841, '1 Chronicles 5:9', '1 Chronicles', 5, 9, '&nbsp;د جِلعاد په مُلک کښې د هغوئ ډېر څاروى وُو او هغه مُلک يې ونيولو چې نمرخاتۀ طرف ته د صحرا د لمنې او د فرات سيند پورې خور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9842, '1 Chronicles 5:10', '1 Chronicles', 5, 10, '&nbsp;د ساؤل بادشاه په وخت کښې د روبين قبيلې په هاجريانو حمله وکړه، هغوئ يې په جنګ کښې ووژل او د جِلعاد نمرخاتۀ ته په ټوله برخه کښې د هغوئ په خېمو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9843, '1 Chronicles 5:11', '1 Chronicles', 5, 11, '&nbsp;د جاد قبيله د بسن په مُلک کښې د روبين شمال ته د سلکه نمرخاتۀ طرف پورې اوسېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9844, '1 Chronicles 5:12', '1 Chronicles', 5, 12, '&nbsp;يوايل په بسن کښې مشر وو، سافم ورپسې دوېم کس وو او درېم مشر يعنې او د هغۀ نه پس سافط وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9845, '1 Chronicles 5:13', '1 Chronicles', 5, 13, '&nbsp;د دې اوو ډلو د قبيلې نور کسان دا دى: ميکائيل، مسلام، شيبا، يورى، يعکان، زيع او عِبر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9846, '1 Chronicles 5:14', '1 Chronicles', 5, 14, '&nbsp;هغوئ د حُورى زوئ ابى‌خېل اولاد دے، چې د هغوئ پلار نيکۀ دا دى: ابى‌خېل، حُورى، يارواح، جِلعاد، ميکائيل، يسيسى، يحدو او بُوز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9847, '1 Chronicles 5:15', '1 Chronicles', 5, 15, '&nbsp;اخى چې د عبدى‌ايل زوئ او د جونى نمسے وو هغه د دې ډلو مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9848, '1 Chronicles 5:16', '1 Chronicles', 5, 16, '&nbsp;هغوئ د بسن او جِلعاد په علاقه کښې، هلته په ښارونو او د شارون د څرن په ټولو مُلکونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9849, '1 Chronicles 5:17', '1 Chronicles', 5, 17, '&nbsp;دا نسب‌نامه د يهوداه بادشاه يوتام او د اِسرائيل بادشاه يربعام په وخت کښې ليکلے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9850, '1 Chronicles 5:18', '1 Chronicles', 5, 18, '&nbsp;د روبين، جاد او د نمرخاتۀ طرف منسى په قبيلو کښې څلور څلوېښت زره اووۀ سوه او شپېتۀ فوجيان وُو، چې د ډالونو، تُورو او غشو په وړلو او استعمالولو باندې ښۀ پوهېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9851, '1 Chronicles 5:19', '1 Chronicles', 5, 19, '&nbsp;هغوئ د جنګ دپاره د يطور، نفيس او نودب هاجرى قبيلو خِلاف لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9852, '1 Chronicles 5:20', '1 Chronicles', 5, 20, '&nbsp;د جنګ په وخت کښې هغوئ خُدائ پاک ته سوال وکړو، هغۀ د هغوئ فرياد واورېدو ځکه چې په هغۀ باندې يې ايمان لرلو. نو داسې هاجريانو او د هغوئ ټولو ملګرو شکست وخوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9853, '1 Chronicles 5:21', '1 Chronicles', 5, 21, '&nbsp;د بنى اِسرائيلو نمرخاتۀ طرف ته قبيلو د دشمن نه پنځوس زره اوښان، دوه لاکه او پنځوس زره ګډې او دوه زره خرۀ ونيول او سل زره کسان يې جنګى قېديان کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9854, '1 Chronicles 5:22', '1 Chronicles', 5, 22, '&nbsp;هغوئ ډېر دشمنان ووژل، ځکه چې خُدائ پاک په دې جنګ کښې د هغوئ مل وو. او هغوئ تر جلاوطنۍ پورې د هاجريانو په علاقه کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9855, '1 Chronicles 5:23', '1 Chronicles', 5, 23, '&nbsp;د منسى نيمې قبيلې خلق د بسن په علاقه کښې د بعل حرمون، سنير او حرمون غر پورې اوسېدل او د هغوئ آبادى ډېره زياته شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9856, '1 Chronicles 5:24', '1 Chronicles', 5, 24, '&nbsp;دا کسان د خپلو ډلو مشران وُو: عِفر، يسعى، اِلى‌ايل، عزرائيل، يرمياه، هُوداوياه او يحدِاېل. هغوئ ټول ښۀ تکړه فوجيان او د خپلو ډلو مشهور مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9857, '1 Chronicles 5:25', '1 Chronicles', 5, 25, '&nbsp;خو خلقو د خپل پلار نيکۀ خُدائ پاک سره خيانت وکړو او د هغه نورو قومونو د معبودانو د عبادت په وجه يې د هغۀ خِلاف بغاوت وکړو کوم قومونه چې خُدائ پاک په هغه وخت تباه کړى وُو چې بنى اِسرائيليان مخ په وړاندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9858, '1 Chronicles 5:26', '1 Chronicles', 5, 26, '&nbsp;نو خُدائ پاک د اسور بادشاه پول ولېږلو چې د هغوئ په مُلک حمله وکړى (چې هغه په تغلت فلاسر باندې هم مشهور وو). هغۀ د روبين، جاد او د منسى نيمه قبيله وويستله او دې ته يې مجبور کړل چې تر نن پورې په خلح، خابور، هارا او د جوزان سيند سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9859, '1 Chronicles 6:1', '1 Chronicles', 6, 1, '&nbsp;د ليوى درې زامن وُو: جيرسون، قُهات او مرارى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
